import{teams,colors,projects,rows,recommendations,sum,allocation,commitment}from'./data.js';
const $=s=>document.querySelector(s);const money=(c,d=0)=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:d}).format(c/100);const pct=n=>new Intl.NumberFormat('fr-FR',{maximumFractionDigits:1}).format(n)+' %';const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={view:'overview',month:9,team:'all',owners:{},method:'usage',statuses:{},decisions:[],commit:65,usage:85,discount:28,base:18000,recFilter:'all'};
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',spark:'m13 2-9 12h7l-1 8 10-12h-7z',layers:'m12 3 10 5-10 5L2 8z M2 12l10 5 10-5 M2 16l10 5 10-5',sliders:'M4 21v-7m0-4V3m8 18v-9m0-4V3m8 18v-4m0-4V3 M1 10h6 M9 8h6 M17 17h6',book:'M4 3h6c2 0 2 2 2 2s0-2 2-2h6v16h-6c-2 0-2 2-2 2s0-2-2-2H4z M12 5v16',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',download:'M12 3v12m-5-5 5 5 5-5 M4 16v5h16v-5',cloud:'M6 18a4 4 0 0 1-1-8 7 7 0 0 1 13-1 4.5 4.5 0 0 1 0 9z',euro:'M18 5a7 7 0 1 0 0 14 M3 10h12 M3 14h10',trend:'m3 17 6-6 4 4 8-11 M15 4h6v6',target:'M21 12a9 9 0 1 1-9-9 M17 12a5 5 0 1 1-5-5 M12 12l9-9 M16 3h5v5',tag:'M3 3h8l10 10-8 8L3 11z M7 7h.01',calendar:'M4 5h16v16H4z M4 10h16 M8 3v4 M16 3v4',clock:'M12 8v5l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',alert:'m12 3 10 18H2z M12 9v5 M12 17h.01',arrow:'M4 12h16m-6-6 6 6-6 6',close:'m6 6 12 12 M6 18 18 6',check:'m5 12 4 4L19 6',reset:'M3 10a9 9 0 1 1 0 5 M3 3v7h7',shield:'m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6z M8 12l3 3 5-6',code:'m8 7-5 5 5 5 M16 7l5 5-5 5 M14 4l-4 16',info:'M12 11v6 M12 7h.01 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;
const views=[['overview','grid','Vue d’ensemble'],['optimise','spark','Optimisations'],['allocation','layers','Allocation'],['simulate','sliders','Simulateur CUD'],['method','book','Méthode & données']];
function selected(){return rows.filter(r=>r.month===state.month&&(state.team==='all'||(state.owners[r.project]||projects.find(p=>p.id===r.project).team)===state.team));}
function available(){return recommendations.filter(r=>state.team==='all'||(state.owners[r.project]||projects.find(p=>p.id===r.project).team)===state.team);}
function totals(input=selected()){const days=state.month===9?15:31;const total=sum(input,r=>r.cost),last=sum(input.filter(r=>r.day>days-7),r=>r.cost);const forecast=state.month===9?total+Math.round(last/7*15):total;const ps=projects.filter(p=>state.team==='all'||(state.owners[p.id]||p.team)===state.team);const budget=sum(ps,p=>p.budget)*100;const previous=rows.filter(r=>r.month===8&&r.day<=15&&(state.team==='all'||(state.owners[r.project]||projects.find(p=>p.id===r.project).team)===state.team));return{total,forecast,budget,days,delta:sum(previous,r=>r.cost)?(total/sum(previous,r=>r.cost)-1)*100:0};}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function filters(){return`<div class="filters"><label><span class="sr-only">Période</span><select id="period" class="select"><option value="9" ${state.month===9?'selected':''}>1–15 septembre 2026</option><option value="8" ${state.month===8?'selected':''}>Août 2026 · mois complet</option></select></label><label><span class="sr-only">Équipe</span><select id="team" class="select"><option value="all">Toutes les équipes</option>${[...teams,'Partagé'].map(t=>`<option ${state.team===t?'selected':''}>${t}</option>`).join('')}</select></label><span class="filter-note">${icon('clock')} Arrêté au ${state.month===9?'15 sept.':'31 août'} 2026 · EUR hors taxes</span></div>`;}
function kpi(title,value,note,ico,extra='',accent=false){return`<div class="kpi ${accent?'accent':''}"><div class="kpi-title">${title}${icon(ico)}</div><div class="kpi-value">${value}</div><div class="kpi-footer">${extra}${note}</div></div>`;}
function head(title,subtitle,actions=''){return`<div class="page-head"><div><div class="eyebrow">Pilotage cloud / Google Cloud</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="toolbar">${actions}</div></div>`;}
function shell(){const current=views.find(v=>v[0]===state.view);$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-symbol"><svg width="24" height="24" viewBox="0 0 24 24" aria-hidden="true"><path d="m12 3 9 17H3zm0 7-3 6h6z" fill="currentColor" fill-rule="evenodd"/></svg></span><span class="brand-name">stratus</span></div><div class="workspace"><span class="cloud-dot">${icon('cloud')}</span><div>Cloud Workspace<small>Organisation de démonstration</small></div></div><div class="nav-label">Espace FinOps</div><nav class="nav" aria-label="Navigation principale">${views.map(([id,ico,label])=>`<button data-nav="${id}" class="${state.view===id?'active':''}" ${state.view===id?'aria-current="page"':''}>${icon(ico)}<span class="nav-text">${label}</span>${id==='optimise'?'<span class="count">4</span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note"><span class="demo-dot"></span>Environnement de démonstration<br>Données synthétiques · aucun accès GCP</div><div class="profile"><div class="avatar">JE</div><div>Julien Esnault<small>Cloud & FinOps Engineer</small></div></div></div></aside><div class="body"><header class="topbar"><div class="breadcrumb">Espace FinOps <span>/</span> <strong>${current[2]}</strong></div><div class="top-right"><span>${icon('shield').replace('class="icon','style="width:13px;height:13px;vertical-align:middle;margin-right:5px" class="icon')} Espace privé</span><span class="demo-pill">DEMO · GCP</span><span class="top-avatar">JE</span></div></header><main id="main" tabindex="-1"></main></div></div>`;renderView();}
function renderView(){const renders={overview,optimise,allocation:allocationView,simulate,method};$('#main').innerHTML=renders[state.view]()+`<footer class="foot"><span>Stratus · Conçu par Julien Esnault</span><span>Données synthétiques · Décisions simulées dans cette session</span></footer>`;bind();}
function chart(input){const n=state.month===9?15:31;const current=Array.from({length:n},(_,i)=>sum(input.filter(r=>r.day===i+1),r=>r.cost)/100);const prev=Array.from({length:n},(_,i)=>sum(rows.filter(r=>r.month===8&&r.day===i+1&&(state.team==='all'||(state.owners[r.project]||projects.find(p=>p.id===r.project).team)===state.team)),r=>r.cost)/100);const max=Math.ceil(Math.max(...current,...prev)/2000)*2000||2000;const x=i=>49+i*625/(n-1),y=v=>189-v/max*150;const line=a=>a.map((v,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${y(v).toFixed(1)}`).join(' ');const area=line(current)+` L674,189 L49,189 Z`;return`<svg viewBox="0 0 708 220" role="img" aria-label="Dépenses quotidiennes, ${state.month===9?'septembre comparé à août':'août'}, en euros"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#a394ed" stop-opacity=".22"/><stop offset="1" stop-color="#a394ed" stop-opacity=".02"/></linearGradient></defs>${Array.from({length:4},(_,i)=>{const value=max*i/3;return`<line x1="49" y1="${y(value)}" x2="674" y2="${y(value)}" stroke="#eef0f5"/><text x="2" y="${y(value)+4}">${(value/1000).toFixed(0)} k€</text>`}).join('')}<path d="${area}" fill="url(#area)"/>${state.month===9?`<path d="${line(prev)}" fill="none" stroke="#c4c9d8" stroke-width="2" stroke-dasharray="5 5"/>`:''}<path d="${line(current)}" fill="none" stroke="#9580e7" stroke-width="2.6" stroke-linejoin="round"/>${state.month===9&&(state.team==='all'||state.team==='Data & IA')?`<line x1="${x(10)}" y1="32" x2="${x(10)}" y2="190" stroke="#dca66e" stroke-dasharray="3 4"/><circle cx="${x(10)}" cy="${y(current[10])}" r="4" fill="#d7a367" stroke="white" stroke-width="2"/><rect x="${x(10)-39}" y="11" width="78" height="19" rx="4" fill="#fbf0e4"/><text class="annotation" x="${x(10)}" y="24" text-anchor="middle">Dérive BigQuery</text>`:''}${current.map((v,i)=>i%Math.ceil(n/6)===0||i===n-1?`<text x="${x(i)}" y="212" text-anchor="middle">${String(i+1).padStart(2,'0')} ${state.month===9?'sept.':'août'}</text>`:'').join('')}</svg>`;}
function services(input){const all={};input.forEach(r=>all[r.service]=(all[r.service]||0)+r.cost);const sorted=Object.entries(all).sort((a,b)=>b[1]-a[1]);const displayed=[...sorted.slice(0,4)];if(sorted.length>4)displayed.push(['Autres',sum(sorted.slice(4),r=>r[1])]);const total=sum(input,r=>r.cost);let offset=0;return`<section class="panel services-panel"><div class="panel-head"><div><h2>Répartition par service</h2><p>Coûts nets sur la période</p></div>${icon('layers')}</div><div class="donut-wrap"><div class="donut"><svg viewBox="0 0 160 160" aria-label="Répartition des dépenses par service" role="img">${displayed.map(([name,v],i)=>{const percent=v/total*100;const s=`<circle cx="80" cy="80" r="65" pathLength="100" stroke="${colors[i]}" fill="none" stroke-width="17" stroke-dasharray="${Math.max(percent-.9,0)} ${100-Math.max(percent-.9,0)}" stroke-dashoffset="${-offset}"/>`;offset+=percent;return s}).join('')}</svg><div class="donut-inner"><strong>${sorted.length}</strong><span>services GCP</span></div></div><div class="donut-description">Premier poste<strong>${sorted[0]?.[0]||'—'}</strong>${pct(total?(sorted[0]?.[1]||0)/total*100:0)} des dépenses</div></div><div class="service-list">${displayed.map(([s,v],i)=>`<div class="service-row"><i style="background:${colors[i]}"></i>${s}<span class="amt">${money(v)}</span><small>${Math.round(v/total*100)} %</small></div>`).join('')}</div></section>`;}
function projectTable(input){const total=totals(input);const ps=projects.map(p=>({...p,cost:sum(input.filter(r=>r.project===p.id),r=>r.cost)})).filter(p=>p.cost).sort((a,b)=>b.cost-a.cost);return`<section class="panel"><div class="panel-head"><div><h2>Vos projets GCP <span class="pill-count">${ps.length} projets</span></h2><p>Suivre les dépenses au plus près des usages.</p></div><button class="button quiet small" data-action="export">Exporter ${icon('download')}</button></div><div class="table-scroll"><table><thead><tr><th>Projet</th><th>Équipe</th><th>Environnement</th><th style="text-align:right">Dépenses</th><th style="text-align:right">Budget consommé</th><th><span class="sr-only">Détails</span></th></tr></thead><tbody>${ps.map((p,i)=>`<tr><td><button class="text-button" data-project="${p.id}"><span class="project-cell"><span class="project-initial" style="background:${['#eeebf9','#eaf1fa','#eaf6f2','#fcf3e6'][i%4]}">${p.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</span><span><strong>${p.name}</strong><small>${p.id}</small></span></span></button></td><td>${state.owners[p.id]||p.team||'<span class="tag orange">À attribuer</span>'}</td><td><span class="tag ${p.env==='Production'?'green':p.env==='Préproduction'?'purple':'gray'}">${p.env}</span></td><td class="money">${money(p.cost)}</td><td><div class="budget-cell"><div class="budget-track"><span style="width:${Math.min(100,p.cost/(p.budget*100)*100)}%"></span></div>${Math.round(p.cost/(p.budget*100)*100)} %</div></td><td><button class="row-open" data-project="${p.id}" aria-label="Voir ${p.name}">${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div></section>`;}
function overview(){const input=selected(),t=totals(input),a={unallocated:sum(input.filter(r=>!(state.owners[r.project]||projects.find(p=>p.id===r.project).team)),r=>r.cost)},potential=sum(available().filter(r=>state.statuses[r.id]!=='rejected'),r=>r.saving);const anomaly=state.month===9&&(state.team==='all'||state.team==='Data & IA');return head('Chaque euro, une décision.','Les coûts de votre cloud, les leviers pour agir.',`<button class="button" data-action="export">${icon('download')} Exporter les données</button>`)+filters()+`<div class="kpis">${kpi('Dépenses à date',money(t.total),state.month===9?'vs 1–15 août':'Mois clôturé','euro',state.month===9?`<span class="change ${t.delta<0?'good':''}">${t.delta>0?'+':''}${pct(t.delta)}</span>`:'')}${kpi(state.month===9?'Projection fin de mois':'Total mensuel',money(t.forecast),`Budget : ${money(t.budget)}`,'trend',`<span class="change ${t.forecast<t.budget?'good':''}">${Math.round(t.forecast/t.budget*100)} %</span>`)}${kpi('Potentiel d’optimisation',money(potential),`${available().length} pistes · estimation / mois`,'spark','',true)}${kpi('Coûts attribués',pct(t.total?(1-a.unallocated/t.total)*100:100),`${money(a.unallocated)} restent à attribuer`,'tag')}</div><div class="main-grid"><section class="panel"><div class="panel-head"><div><h2>Évolution des dépenses</h2><p>Consommation quotidienne en euros</p></div><div class="legend"><span><i></i>${state.month===9?'Septembre':'Août'}</span>${state.month===9?'<span><i class="line"></i>Août</span>':''}</div></div><div class="chart">${chart(input)}</div><div class="chart-caption">${icon('info')}${state.month===9?'Projection : réalisé + moyenne des 7 derniers jours × jours restants.':'Période clôturée : la projection correspond au réalisé.'}</div></section>${services(input)}</div>${anomaly?`<div class="alert-banner"><div class="alert-symbol">${icon('alert')}</div><div class="alert-text"><strong>Une dérive BigQuery mérite votre attention</strong>Atlas Analytics · hausse des octets lus depuis le 11 septembre.</div><button class="button small" data-rec="bq-partition">Examiner la dérive ${icon('arrow')}</button></div>`:''}${projectTable(input)}`;}

const statusNames={candidate:'À qualifier',approved:'Validée',implemented:'Déployée · à mesurer',rejected:'Écartée'};
function statusOf(id){return state.statuses[id]||'candidate'}
function optimise(){const recs=available(),visible=recs.filter(r=>state.recFilter==='all'||statusOf(r.id)===state.recFilter);const approved=recs.filter(r=>['approved','implemented'].includes(statusOf(r.id)));return head('Optimiser sans fragiliser.','Pistes identifiées au 15 septembre 2026 · décisions traçables et gains à vérifier.')+`<div class="filters"><label><span class="sr-only">Équipe</span><select id="team" class="select"><option value="all">Toutes les équipes</option>${[...teams,'Partagé'].map(t=>`<option ${state.team===t?'selected':''}>${t}</option>`).join('')}</select></label><span class="filter-note">Estimations mensuelles · indépendantes de la période du tableau de bord</span></div>`+`<div class="kpis">${kpi('Potentiel identifié',money(sum(recs.filter(r=>statusOf(r.id)!=='rejected'),r=>r.saving)),'Estimation mensuelle · hors CUD','spark','',true)}${kpi('Actions validées',String(approved.length),`${money(sum(approved,r=>r.saving))} / mois estimés`,'check')}${kpi('Gains constatés','Non mesurés','Nécessitent des données après action','target')}${kpi('Risque opérationnel','À maîtriser','Garde-fous définis pour chaque action','shield')}</div><div class="section-toolbar"><h2>Plan d’optimisation <span class="pill-count">${recs.length} pistes</span></h2><label><span class="sr-only">Filtrer les recommandations</span><select id="rec-filter" class="select"><option value="all">Tous les statuts</option>${Object.entries(statusNames).map(([id,label])=>`<option value="${id}" ${state.recFilter===id?'selected':''}>${label}</option>`).join('')}</select></label></div><div class="rec-list">${visible.length?visible.map(r=>`<article class="rec-card"><div class="rec-icon">${icon(r.service==='BigQuery'?'code':r.service==='Cloud Storage'?'layers':'cloud')}</div><div class="rec-copy"><div class="rec-meta"><span>${r.service}</span><span>·</span><span>${r.project}</span></div><h3><button class="text-button" data-rec="${r.id}">${r.title}</button></h3><p>${r.description}</p><div class="rec-tags"><span class="tag ${r.risk==='Faible'?'green':'orange'}">Risque ${r.risk.toLowerCase()}</span><span class="tag gray">${r.effort}</span><span class="tag ${statusOf(r.id)==='rejected'?'gray':'purple'}">${statusNames[statusOf(r.id)]}</span></div></div><div class="rec-gain"><strong>${money(r.saving)}</strong><span>potentiel / mois</span><button class="button small" data-rec="${r.id}">Examiner ${icon('arrow')}</button></div></article>`).join(''):'<div class="panel empty">Aucune recommandation pour ce statut et cette équipe.</div>'}</div><section class="panel section-gap"><div class="panel-head"><div><h2>Journal des décisions</h2><p>Les décisions de démonstration restent dans cet onglet du navigateur.</p></div><button class="button small quiet" data-action="export-decisions">Exporter ${icon('download')}</button></div>${state.decisions.length?`<div class="decision-list">${state.decisions.slice().reverse().map(d=>`<div><span class="decision-mark">${icon('check')}</span><p><strong>${esc(recommendations.find(r=>r.id===d.id).title)}</strong><span>${statusNames[d.status]} · ${esc(d.note)}</span></p><time>${new Date(d.at).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}</time></div>`).join('')}</div>`:'<div class="empty small-empty">Examinez une recommandation pour qualifier votre première action.</div>'}</section>`;}
function allocationView(){const input=rows.filter(r=>r.month===state.month),a=allocation(input,state.owners,state.method),unknown=projects.filter(p=>!p.team&&!state.owners[p.id]),allocated=sum(a.items,x=>x.total);return head('Donner un propriétaire à chaque coût.','Une allocation explicable, des montants réconciliés au centime.',`<button class="button" data-action="export-allocation">${icon('download')} Export showback</button><button class="button primary" data-action="export-chargeback" ${a.unallocated?'disabled title="Attribuez tous les coûts avant de préparer le chargeback"':''}>Préparer le chargeback ${icon('arrow')}</button>`)+`<div class="filters"><label><span class="sr-only">Période d’allocation</span><select class="select" id="period"><option value="9" ${state.month===9?'selected':''}>1–15 septembre 2026</option><option value="8" ${state.month===8?'selected':''}>Août 2026 · mois complet</option></select></label><span class="scope-label">Organisation entière · coûts partagés inclus</span><span class="filter-note">${icon('shield')} Brouillon de refacturation · aucun transfert comptable</span></div><div class="kpis">${kpi('Total à répartir',money(a.total),'Coûts nets GCP sur la période','euro')}${kpi('Coûts mutualisés',money(a.shared),'Réseau et socle commun','layers')}${kpi('Coûts sans équipe',money(a.unallocated),a.unallocated?'Une affectation est nécessaire':'Tous les coûts sont attribués','tag','',!!a.unallocated)}${kpi('Écart de rapprochement',money(a.total-allocated-a.unallocated,2),'Total = équipes + non attribué','check',`<span class="change good">OK</span>`)}</div>${unknown.length?`<div class="allocation-warning"><div>${icon('alert')}<div><h3>Une équipe manque pour Sandbox R&D</h3><p>${money(a.unallocated)} ne peuvent pas encore être refacturés. Choisissez le responsable.</p></div></div><div class="toolbar"><label><span class="sr-only">Équipe responsable de Sandbox R&D</span><select id="assign-owner" class="select">${teams.map(t=>`<option ${t==='Innovation'?'selected':''}>${t}</option>`).join('')}</select></label><button class="button dark" data-action="assign">Attribuer</button></div></div>`:`<div class="success-line">${icon('check')} Les coûts sont entièrement attribués. Le brouillon de chargeback peut être préparé.</div>`}<section class="panel"><div class="panel-head"><div><h2>Répartition par équipe</h2><p>Les coûts directs sont conservés ; seul le socle partagé est redistribué.</p></div><label class="inline-label">Clé de partage<select class="select" id="allocation-method"><option value="usage" ${state.method==='usage'?'selected':''}>Prorata des coûts directs</option><option value="equal" ${state.method==='equal'?'selected':''}>Parts égales</option></select></label></div><div class="allocation-bars">${a.items.map((r,i)=>`<div><span class="allocation-team"><i style="background:${colors[i]}"></i>${r.team}</span><div class="allocation-track"><span style="width:${a.total?r.direct/a.total*100:0}%;background:${colors[i]}"></span><span class="shared-part" style="width:${a.total?r.shared/a.total*100:0}%"></span></div><strong>${money(r.total)}</strong></div>`).join('')}</div><div class="allocation-legend"><span><i></i>Coûts directs</span><span><i class="striped"></i>Quote-part du socle partagé</span></div><div class="table-scroll"><table><thead><tr><th>Équipe</th><th class="money">Coûts directs</th><th class="money">Socle partagé</th><th class="money">Total alloué</th><th class="money">Part du total</th></tr></thead><tbody>${a.items.map(r=>`<tr><td>${r.team}</td><td class="money">${money(r.direct,2)}</td><td class="money">${money(r.shared,2)}</td><td class="money">${money(r.total,2)}</td><td class="money">${pct(r.total/a.total*100)}</td></tr>`).join('')}${a.unallocated?`<tr><td><span class="tag orange">Non attribué</span></td><td class="money">${money(a.unallocated,2)}</td><td class="money">—</td><td class="money">${money(a.unallocated,2)}</td><td class="money">${pct(a.unallocated/a.total*100)}</td></tr>`:''}<tr class="total-row"><td>Total réconcilié</td><td class="money">${money(a.totalDirect+a.unallocated,2)}</td><td class="money">${money(a.shared,2)}</td><td class="money">${money(a.total,2)}</td><td class="money">100 %</td></tr></tbody></table></div><div class="panel-note">Les centimes résiduels sont attribués selon les plus forts restes. ${state.method==='usage'?'La clé dépend des dépenses directes connues, sans utiliser les coûts non attribués.':'Le socle partagé est divisé entre les quatre équipes.'} ${state.month===9?'Septembre est une période partielle : tout export de chargeback reste provisoire.':''}</div></section>`;}
function simulate(){return head('Le bon engagement. Pas le plus grand.','Mesurer le gain attendu et le risque d’une baisse d’usage.')+`<div class="sim-layout"><section class="panel sim-controls"><div class="panel-head"><div><h2>Hypothèses du scénario</h2><p>Compute éligible · modèle mensuel simplifié</p></div>${icon('sliders')}</div><div class="control-body"><label class="input-label" for="base">Dépense à la demande à 100 % d’usage</label><div class="number-field"><input id="base" type="number" min="100" max="1000000" step="100" value="${state.base}" inputmode="decimal"><span>€ / mois</span></div><div class="range-control"><label for="usage">Niveau d’usage réel <output id="usage-output">${state.usage} %</output></label><input id="usage" type="range" min="20" max="120" value="${state.usage}"><div class="range-scale"><span>20 % · contraction</span><span>120 % · croissance</span></div></div><div class="range-control"><label for="commit">Capacité engagée <output id="commit-output">${state.commit} %</output></label><input id="commit" type="range" min="0" max="100" value="${state.commit}"><div class="range-scale"><span>0 %</span><span>100 % du socle</span></div></div><div class="range-control"><label for="discount">Remise hypothétique <output id="discount-output">${state.discount} %</output></label><input id="discount" type="range" min="10" max="60" value="${state.discount}"><div class="range-scale"><span>10 %</span><span>60 %</span></div></div><div class="scenario-presets"><span>Explorer un scénario</span><div><button class="button small" data-scenario="stable">Usage stable</button><button class="button small" data-scenario="drop">Usage à 40 %</button><button class="button small" data-scenario="none">Sans engagement</button></div></div></div><div class="panel-note">Paramètres illustratifs, sans valeur de devis. Le calcul exclut taxes, change, autres remises et granularité horaire. Aucun engagement n’est acheté.</div></section><div id="simulation-results"></div></div>`;}
function simResults(){const r=commitment(state.base,state.usage,state.commit,state.discount);const max=state.base*1.3;const breakeven=state.commit*(1-state.discount/100);const positions=[...new Set([...Array.from({length:13},(_,i)=>i*10),state.commit])].sort((a,b)=>a-b);const x=u=>45+u/120*545,y=v=>185-v/max*150;const line=fn=>positions.map((u,i)=>`${i?'L':'M'}${x(u)},${y(fn(u))}`).join(' ');return`<div class="sim-summary"><span class="eyebrow">Impact mensuel estimé</span><strong class="${r.saving>=0?'positive':'negative'}">${r.saving<0?'+':'−'}${money(Math.round(Math.abs(r.saving)*100))}</strong><p>${r.saving<0?'Surcoût lié à un engagement trop élevé.':r.saving===0?'Aucun écart avec la facturation à la demande.':'Économie par rapport à la facturation à la demande.'}</p><span class="tag ${r.saving<0?'orange':'green'}">${r.saving===0?'Neutre':r.saving<0?'Scénario défavorable':'Scénario favorable'} à ${state.usage} % d’usage</span></div><section class="panel section-gap"><div class="panel-head"><div><h2>Et si l’usage change ?</h2><p>Coût mensuel selon l’utilisation du socle</p></div></div><div class="legend sim-legend"><span><i class="line"></i>À la demande</span><span><i></i>Avec engagement</span></div><div class="chart"><svg viewBox="0 0 625 230" role="img" aria-label="Comparaison des coûts selon l’usage"><line x1="45" y1="185" x2="590" y2="185" stroke="#e6e9f0"/>${[0,.5,1].map(k=>`<line x1="45" y1="${y(state.base*k)}" x2="590" y2="${y(state.base*k)}" stroke="#edf0f5"/><text x="0" y="${y(state.base*k)+3}">${(state.base*k/1000).toFixed(0)} k€</text>`).join('')}<path d="${line(u=>state.base*u/100)}" fill="none" stroke="#b5becf" stroke-dasharray="5 5" stroke-width="2"/><path d="${line(u=>commitment(state.base,u,state.commit,state.discount).cost)}" fill="none" stroke="#8b76de" stroke-width="3"/><line x1="${x(state.usage)}" x2="${x(state.usage)}" y1="23" y2="185" stroke="#8b76de" stroke-dasharray="3 4"/><circle cx="${x(state.usage)}" cy="${y(r.cost)}" r="5" fill="#8b76de" stroke="white" stroke-width="2"/>${[0,30,60,90,120].map(u=>`<text x="${x(u)}" y="211" text-anchor="middle">${u} %</text>`).join('')}</svg></div><div class="sim-breakdown"><div><span>À la demande</span><strong>${money(Math.round(r.actual*100))}</strong></div><div><span>Engagement fixe</span><strong>${money(Math.round(r.fee*100))}</strong></div><div><span>Usage au-delà</span><strong>${money(Math.round(r.overflow*100))}</strong></div><div class="highlight"><span>Total avec engagement</span><strong>${money(Math.round(r.cost*100))}</strong></div></div></section><div class="sim-insight"><span>${icon(r.unused?'alert':'shield')}</span><div><h3>${r.unused?`${money(Math.round(r.unused*100))} d’engagement inutilisé`:'Conserver une marge avant de s’engager'}</h3><p>${state.commit?`L’engagement devient rentable au-delà de ${pct(breakeven)} d’usage du socle dans ce modèle. Taux d’utilisation de l’engagement : ${pct(r.utilization)}.`:'Sans engagement, toute la consommation reste à la demande.'} Le gain CUD ne s’ajoute pas automatiquement aux gains de rightsizing.</p></div></div>`;}
function method(){return head('Des chiffres que l’on peut expliquer.','Périmètre, règles de calcul et passage à un export GCP réel.',`<button class="button" data-action="reset">${icon('reset')} Réinitialiser la démo</button>`)+`<section class="guide"><div class="eyebrow">Parcours guidé · 5 minutes</div><h2>De la facture à la décision</h2><div class="guide-steps"><button data-nav="overview"><span>01</span><strong>Observer</strong><small>Repérer la dérive BigQuery</small>${icon('arrow')}</button><button data-guide="bq-partition"><span>02</span><strong>Qualifier</strong><small>Justifier l’action et ses garde-fous</small>${icon('arrow')}</button><button data-nav="allocation"><span>03</span><strong>Responsabiliser</strong><small>Attribuer puis rapprocher les coûts</small>${icon('arrow')}</button><button data-nav="simulate"><span>04</span><strong>Arbitrer</strong><small>Tester le risque d’engagement</small>${icon('arrow')}</button></div></section><div class="two-columns section-gap"><section class="panel method-panel"><h2>Un périmètre volontairement transparent</h2><p>8 projets fictifs, 4 équipes, 6 services GCP et 2 régions européennes. Les données couvrent août 2026 et les 15 premiers jours de septembre.</p><p>Un générateur déterministe produit les mêmes lignes à chaque ouverture : variation quotidienne, activité réduite le week-end et surconsommation BigQuery à partir du 11 septembre.</p><div class="method-fact">${icon('shield')}Aucune donnée SFR ou Thales. Aucun compte cloud connecté.</div><p>Les affectations et décisions sont mémorisées uniquement dans la session de cet onglet. Fermer l’onglet ou réinitialiser la démo efface ces modifications.</p><details><summary>Voir les règles de calcul</summary><dl><dt>Coût net</dt><dd>Coût brut + crédits négatifs. Crédit illustratif de 2 %, hors taxes. Pas d’engagement préexistant dans le jeu de données.</dd><dt>Projection</dt><dd>Septembre : réalisé du 1 au 15 + moyenne quotidienne des 7 derniers jours × 15 jours restants. Extrapolation simple, sans intervalle de confiance ; la dérive affecte la prévision.</dd><dt>Comparaison</dt><dd>Septembre du 1 au 15 comparé à août du 1 au 15. Les budgets sont mensuels, les dépenses à date couvrent la période choisie.</dd><dt>Potentiel</dt><dd>Somme des estimations des actions non écartées, sur des ressources distinctes. Aucune économie constatée n’est inventée. Les CUD sont simulés séparément.</dd><dt>Répartition</dt><dd>Coûts directs par équipe et redistribution du socle partagé au prorata ou à parts égales. Les coûts non attribués restent visibles et bloquent le brouillon de chargeback.</dd><dt>Arrondis</dt><dd>Calcul des coûts en centimes entiers. Allocation du reliquat aux plus forts restes. Les KPI sont arrondis à l’euro, les exports conservent les centimes.</dd></dl></details></section><section class="panel method-panel"><h2>Passer à des données GCP réelles</h2><ol class="pipeline"><li><strong>Cloud Billing → BigQuery</strong><span>Activer l’export de facturation dans un projet dédié et autoriser la lecture du dataset selon le moindre privilège.</span></li><li><strong>Normaliser et réconcilier</strong><span>Contrôler les crédits, la devise, les périodes de consommation et de facturation, les corrections et les engagements amortis.</span></li><li><strong>Attribuer et enrichir</strong><span>Rapprocher projets, labels et centres de coûts. Joindre les métriques d’usage et les propriétaires applicatifs.</span></li><li><strong>Servir les vues de pilotage</strong><span>Ajouter une API authentifiée, un contrôle d’accès par équipe et un historique auditable des décisions.</span></li></ol><div class="method-fact">${icon('code')}L’export CSV est un extrait de champs alignés sur FOCUS, pas un export FOCUS complet ou certifié.</div><p>Ce prototype ne contient ni connecteur actif, ni moteur de facturation, ni automatisation de ressources. Les recommandations sont des scénarios métier documentés.</p></section></div><section class="panel section-gap method-panel"><h2>Références techniques</h2><div class="reference-grid"><a href="https://docs.cloud.google.com/bigquery/docs/best-practices-costs" target="_blank" rel="noopener noreferrer"><strong>Maîtriser les coûts BigQuery ${icon('arrow')}</strong><span>Estimation des octets lus et maximum bytes billed.</span></a><a href="https://docs.cloud.google.com/docs/cuds-multiprice" target="_blank" rel="noopener noreferrer"><strong>Engagements de consommation ${icon('arrow')}</strong><span>Une dépense engagée reste due même si elle n’est pas utilisée.</span></a><a href="https://docs.cloud.google.com/billing/docs/how-to/export-data-bigquery" target="_blank" rel="noopener noreferrer"><strong>Exporter Cloud Billing ${icon('arrow')}</strong><span>Collecter la facturation GCP dans BigQuery.</span></a></div></section>`;}
function showProject(id){const p=projects.find(p=>p.id===id);const input=selected().filter(r=>r.project===id);$('#detail').innerHTML=`<div class="drawer-header"><h2 id="detail-title">Détail du projet</h2><button class="close" data-close aria-label="Fermer">${icon('close')}</button></div><div class="drawer-content"><span class="tag purple">${p.region}</span><h3>${p.name}</h3><p>${p.id}</p><div class="drawer-stat"><strong>${money(sum(input,r=>r.cost))}</strong><span>Dépenses nettes sur la période sélectionnée</span></div><div class="detail-list"><div><span>Équipe</span><strong>${state.owners[p.id]||p.team||'À attribuer'}</strong></div><div><span>Environnement</span><strong>${p.env}</strong></div><div><span>Budget mensuel</span><strong>${money(p.budget*100)}</strong></div></div><div class="detail-label">Dépenses par service</div>${services(input)}<p style="margin-top:20px">Les montants et les noms de projets sont fictifs. Ils ne correspondent à aucune organisation réelle.</p></div>`;$('#detail').showModal();}

function showRecommendation(id){const r=recommendations.find(r=>r.id===id),status=statusOf(id);$('#detail').innerHTML=`<div class="drawer-header"><h2 id="detail-title">Fiche d’optimisation</h2><button class="close" data-close aria-label="Fermer">${icon('close')}</button></div><div class="drawer-content"><div class="rec-tags"><span class="tag purple">${r.service}</span><span class="tag ${r.risk==='Faible'?'green':'orange'}">Risque ${r.risk.toLowerCase()}</span><span class="tag gray">${statusNames[status]}</span></div><h3>${r.title}</h3><p>${r.evidence}</p><div class="drawer-stat"><strong>${money(r.saving)} / mois</strong><span>Gain estimé · non constaté</span><p>${r.formula}</p></div><div class="detail-label">Action proposée</div><p>${r.action}</p>${r.before?`<details class="sql-example"><summary>Exemple SQL avant / après</summary><div class="code-label">Avant · relit l’historique</div><pre><code>${esc(r.before)}</code></pre><div class="code-label">Après · une partition de traitement</div><pre><code>${esc(r.after)}</code></pre><p>Exemple fictif. @processing_date doit être défini ; la table doit être partitionnée sur event_date. Les rattrapages nécessitent une fenêtre adaptée.</p></details>`:''}<div class="detail-label">Garde-fous opérationnels</div><p>${r.guardrail}</p><div class="detail-label">Mesure après déploiement</div><p>${r.validation}</p><div class="owner-line">${icon('shield')} Responsable : ${r.owner} · effort estimé : ${r.effort}</div><form id="decision-form" data-id="${r.id}"><label for="decision-note">Motif ou conditions de validation</label><textarea id="decision-note" rows="3" placeholder="Ex. Valider en recette avant de modifier la production." maxlength="500" required></textarea><p class="form-help">Un commentaire est obligatoire pour tracer votre décision. Simulation uniquement.</p><div class="decision-actions">${status==='candidate'?`<button type="submit" class="button primary" name="decision" value="approved">${icon('check')} Valider la piste</button><button type="submit" class="button" name="decision" value="rejected">Écarter</button>`:status==='approved'?`<button type="submit" class="button primary" name="decision" value="implemented">Marquer déployée</button><button type="submit" class="button" name="decision" value="rejected">Écarter</button>`:`<button type="submit" class="button" name="decision" value="candidate">Remettre à qualifier</button>`}</div></form></div>`;if(!$('#detail').open)$('#detail').showModal();$('#decision-form').onsubmit=e=>{e.preventDefault();const note=$('#decision-note').value.trim();if(!note){$('#decision-note').setCustomValidity('Ajoutez un motif pour tracer cette décision.');$('#decision-note').reportValidity();return;}const next=e.submitter.value;state.statuses[id]=next;state.decisions.push({id,status:next,note,at:new Date().toISOString()});persist();$('#detail').close();renderView();toast('Décision enregistrée dans cette session. Aucun changement dans GCP.');};$('#decision-note').oninput=e=>e.target.setCustomValidity('');}
function persist(){try{sessionStorage.setItem('stratus-demo-v1',JSON.stringify({owners:state.owners,statuses:state.statuses,decisions:state.decisions,method:state.method}));}catch{}}
function exportAllocation(chargeback=false){const input=rows.filter(r=>r.month===state.month),a=allocation(input,state.owners,state.method);if(chargeback&&a.unallocated){toast('Attribuez les coûts restants avant de préparer le chargeback.');return}const header=['Period','Mode','Team','DirectCostEUR','SharedCostEUR','TotalEUR','AllocationMethod','Status'];const lines=a.items.map(r=>[`2026-${String(state.month).padStart(2,'0')}`,chargeback?'Chargeback':'Showback',r.team,(r.direct/100).toFixed(2),(r.shared/100).toFixed(2),(r.total/100).toFixed(2),state.method,state.month===9?'PROVISOIRE_1_15_SEPTEMBRE':'BROUILLON_A_VALIDER']);if(a.unallocated)lines.push([`2026-${String(state.month).padStart(2,'0')}`,'Showback','Non attribué',(a.unallocated/100).toFixed(2),'0.00',(a.unallocated/100).toFixed(2),state.method,'NON_ATTRIBUE']);download(`stratus-${chargeback?'chargeback-brouillon':'showback'}-2026-${state.month}.csv`,[header,...lines].map(r=>r.join(',')).join('\r\n'));toast(`${chargeback?'Brouillon de chargeback':'Showback'} exporté · total ${money(a.total,2)}`);}
function resetDemo(){state.owners={};state.statuses={};state.decisions=[];state.method='usage';state.team='all';state.month=9;state.recFilter='all';state.commit=65;state.usage=85;state.discount=28;state.base=18000;persist();renderView();toast('Le scénario initial a été restauré.');}
function download(name,text,type='text/csv;charset=utf-8'){const blob=new Blob(['\ufeff',text],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportData(){const input=selected();const header=['ChargePeriodStart','ChargePeriodEnd','ProviderName','SubAccountId','ServiceName','RegionId','BillingCurrency','BilledCost','x_Team','x_Environment'];const text=[header,...input.map(r=>[r.date+'T00:00:00Z',new Date(Date.parse(r.date+'T00:00:00Z')+86400000).toISOString(),'Google Cloud',r.project,r.service,r.region,'EUR',(r.cost/100).toFixed(2),state.owners[r.project]||projects.find(p=>p.id===r.project).team||'Unallocated',r.environment])].map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');download(`stratus-gcp-2026-${state.month}-extrait.csv`,text);toast(`${input.length} lignes exportées · extrait de champs FOCUS`);}

function bind(){const period=$('#period');if(period)period.onchange=e=>{state.month=+e.target.value;renderView()};const team=$('#team');if(team)team.onchange=e=>{state.team=e.target.value;renderView()};const rf=$('#rec-filter');if(rf)rf.onchange=e=>{state.recFilter=e.target.value;renderView()};const am=$('#allocation-method');if(am)am.onchange=e=>{state.method=e.target.value;persist();renderView()};if(state.view==='simulate'){const update=()=>{$('#simulation-results').innerHTML=simResults();};update();['usage','commit','discount'].forEach(id=>{$('#'+id).oninput=e=>{state[id]=+e.target.value;$('#'+id+'-output').textContent=state[id]+' %';update()}});$('#base').oninput=e=>{const v=+e.target.value;if(Number.isFinite(v)&&v>=100&&v<=1000000){state.base=v;update();}};$('#base').onchange=e=>{if(!e.target.checkValidity()){e.target.value=state.base;e.target.reportValidity();}};}}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav){state.view=nav.dataset.nav;shell();window.scrollTo({top:0});$('#main').focus({preventScroll:true});}const p=e.target.closest('[data-project]');if(p)showProject(p.dataset.project);const r=e.target.closest('[data-rec]');if(r)showRecommendation(r.dataset.rec);const guide=e.target.closest('[data-guide]');if(guide){state.view='optimise';shell();showRecommendation(guide.dataset.guide)}if(e.target.closest('[data-close]'))$('#detail').close();const action=e.target.closest('[data-action]')?.dataset.action;if(action==='export')exportData();if(action==='export-allocation')exportAllocation();if(action==='export-chargeback')exportAllocation(true);if(action==='assign'){state.owners['sandbox-experiments']=$('#assign-owner').value;persist();renderView();toast('Sandbox R&D est attribué. La répartition a été recalculée.');}if(action==='export-decisions'){if(!state.decisions.length){toast('Aucune décision à exporter.');return}download('stratus-decisions.json',JSON.stringify(state.decisions.map(d=>({...d,title:recommendations.find(r=>r.id===d.id).title,simulation:true})),null,2),'application/json');toast('Journal des décisions exporté.');}if(action==='reset')resetDemo();const preset=e.target.closest('[data-scenario]')?.dataset.scenario;if(preset){if(preset==='stable'){state.usage=85;state.commit=65;}if(preset==='drop'){state.usage=40;state.commit=85;}if(preset==='none'){state.commit=0;}renderView();}});
try{const saved=JSON.parse(sessionStorage.getItem('stratus-demo-v1')||'null');if(saved){state.owners=Object.fromEntries(Object.entries(saved.owners||{}).filter(([k,v])=>k==='sandbox-experiments'&&teams.includes(v)));state.statuses=Object.fromEntries(Object.entries(saved.statuses||{}).filter(([k,v])=>recommendations.some(r=>r.id===k)&&Object.keys(statusNames).includes(v)));state.decisions=(saved.decisions||[]).filter(d=>recommendations.some(r=>r.id===d.id)&&Object.keys(statusNames).includes(d.status)&&typeof d.note==='string').slice(-100);state.method=saved.method==='equal'?'equal':'usage';}}catch{}
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')&&e.clientX<$('#detail').getBoundingClientRect().left)$('#detail').close()});
shell();
